// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListDisputes The tenant's disputes, newest first
	// (GET /disputes)
	ListDisputes(ctx context.Context, request ListDisputesRequestObject) (ListDisputesResponseObject, error)
	// CreateDispute Open a dispute against a transaction
	// (POST /disputes)
	CreateDispute(ctx context.Context, request CreateDisputeRequestObject) (CreateDisputeResponseObject, error)
	// GetDispute Current state and full event log
	// (GET /disputes/{disputeId})
	GetDispute(ctx context.Context, request GetDisputeRequestObject) (GetDisputeResponseObject, error)
	// ApplyDisputeEvent Apply a lifecycle event
	// (POST /disputes/{disputeId}/events)
	ApplyDisputeEvent(ctx context.Context, request ApplyDisputeEventRequestObject) (ApplyDisputeEventResponseObject, error)
	// GetNotice One communication to the customer, as composed
	// (GET /disputes/{disputeId}/notices/{noticeId})
	GetNotice(ctx context.Context, request GetNoticeRequestObject) (GetNoticeResponseObject, error)
	// GetHealthz Liveness
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// DeleteSessions End every session matching a realm session id or a tenant's subject
	// (DELETE /internal/sessions)
	DeleteSessions(ctx context.Context, request DeleteSessionsRequestObject) (DeleteSessionsResponseObject, error)
	// DeleteSession Remove a session
	// (DELETE /internal/sessions/{sessionId})
	DeleteSession(ctx context.Context, request DeleteSessionRequestObject) (DeleteSessionResponseObject, error)
	// GetSession Fetch a session blob that has not expired
	// (GET /internal/sessions/{sessionId})
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// PutSession Store or replace an opaque session blob
	// (PUT /internal/sessions/{sessionId})
	PutSession(ctx context.Context, request PutSessionRequestObject) (PutSessionResponseObject, error)
	// ListTenants Active tenants with what the sign-in page needs to find their realm
	// (GET /internal/tenants)
	ListTenants(ctx context.Context, request ListTenantsRequestObject) (ListTenantsResponseObject, error)
	// GetReadyz Readiness (database reachable)
	// (GET /readyz)
	GetReadyz(ctx context.Context, request GetReadyzRequestObject) (GetReadyzResponseObject, error)
	// ListTenantKeys The tenant's own keys, live and revoked
	// (GET /tenant-keys)
	ListTenantKeys(ctx context.Context, request ListTenantKeysRequestObject) (ListTenantKeysResponseObject, error)
	// CreateTenantKey Issue a key for one of the tenant's systems
	// (POST /tenant-keys)
	CreateTenantKey(ctx context.Context, request CreateTenantKeyRequestObject) (CreateTenantKeyResponseObject, error)
	// RevokeTenantKey Revoke a key; takes effect on the next request
	// (DELETE /tenant-keys/{keyId})
	RevokeTenantKey(ctx context.Context, request RevokeTenantKeyRequestObject) (RevokeTenantKeyResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

